/* ===================== BÀI 34 · Chế độ minimum và clock/reset ===================== */
/* Bài 34 · Chế độ minimum và clock/reset (AMTS-EMB-002-M09-L02, X86-034) — sinh bởi tools/author/mpu8086/l34.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P34=[{"label": "Ví dụ: bộ nhớ chậm, mỗi chu kỳ bus thêm Tw", "code": "; Ví dụ 1: bộ nhớ chậm - mỗi chu kỳ bus thêm Tw\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nx       DW      1234H\ny       DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, x                   ; 1 chu kỳ đọc: T1 T2 T3 Tw T4\n        MOV     y, AX                   ; 1 chu kỳ ghi: T1 T2 T3 Tw T4\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Ở công cụ chu kỳ bus (Hình 34.4), chương trình này đặt 1 Tw cho bộ nhớ. Bấm Tới chu kỳ bus tiếp: chu kỳ đọc x có 5 trạng thái T1 T2 T3 Tw T4, READY thấp trong T3, RD giữ thấp qua Tw. Lệnh MOV AX, x: 10 chu kỳ theo bảng + 1 = 11. Đoán trước: cả chương trình bao nhiêu chu kỳ khi bộ nhớ có 1 Tw? Đáp án 83 (81 + 2 chu kỳ bus × 1)."}, {"label": "Ví dụ: chỉ thiết bị I/O chậm phải chờ", "code": "; Ví dụ 2: chỉ thiết bị I/O chậm nên chỉ IN, OUT phải chờ\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nv       DB      3CH\nr       DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, v                   ; bộ nhớ nhanh: không chờ\n        MOV     DX, 0304H               ; cổng giả định của thiết bị chậm\n        OUT     DX, AL                  ; READY thấp: thêm Tw\n        IN      AL, DX                  ; READY thấp: thêm Tw\n        MOV     r, AL                   ; bộ nhớ nhanh: không chờ\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Đặt sẵn 0 Tw cho bộ nhớ, 2 Tw cho I/O: mạch giải mã chỉ kéo RDY khi chọn thiết bị chậm ở cổng 0304h (giả định). Hai chu kỳ bộ nhớ vẫn 4 trạng thái T; OUT và IN mỗi lệnh thêm 2. Tổng 101 + 4 = 105 chu kỳ. Đoán trước: chu kỳ IN có mấy trạng thái T? Đáp án 6 (T1 T2 T3 Tw Tw T4)."}, {"label": "Ví dụ: chép từng byte, 8 chu kỳ bus", "code": "; Ví dụ 3: chép 4 byte, mỗi byte 2 chu kỳ bus\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\na       DB      'ABCD'\nb       DB      4 DUP(?)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        LEA     SI, a\n        LEA     DI, b\n        MOV     CX, 4\nchep:\n        MOV     AL, [SI]                ; 1 chu kỳ đọc\n        MOV     [DI], AL                ; 1 chu kỳ ghi\n        INC     SI\n        INC     DI\n        LOOP    chep\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Chép 4 byte bằng MOV qua AL: mỗi byte một chu kỳ đọc và một chu kỳ ghi, tổng 8 chu kỳ bus; 261 chu kỳ không chờ. Đặt 1 Tw cho bộ nhớ: 269. Xem làn dữ liệu: byte ở địa chỉ chẵn đi trên D7–D0, lẻ trên D15–D8. Đoán trước: vòng lặp chạy mấy lần LOOP có nhảy? Đáp án 3."}, {"label": "Sửa: MOVSW chép 2 byte mỗi chu kỳ bus", "code": "; Ví dụ 4 (sửa): MOVSW chép 2 byte mỗi chu kỳ bus\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\na       DB      'ABCD'\nb       DB      4 DUP(?)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     ES, AX                  ; MOVSW ghi vào ES:DI\n        CLD\n        LEA     SI, a\n        LEA     DI, b\n        MOV     CX, 2                   ; 2 word = 4 byte\n        REP     MOVSW                   ; 2 lần đọc word + 2 lần ghi word\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Sửa của Ví dụ 3: REP MOVSW chép 2 word, mỗi chu kỳ bus mang 2 byte (BHE = 0, A0 = 0): còn 4 chu kỳ bus, 128 chu kỳ không chờ, 132 với 1 Tw. Một bước của REP MOVSW chạy hết các lần lặp nên công cụ hiện cả 4 chu kỳ trong một lệnh. Đoán trước: sau lệnh REP MOVSW, CX bằng bao nhiêu? Đáp án 0000h."}, {"label": "Bẫy: word lẻ chịu trạng thái chờ hai lần", "code": "; Ví dụ 5 (bẫy): word lẻ chịu trạng thái chờ hai lần\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nc       DB      0\nw       DW      5678H                   ; độ lệch 1: lẻ\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, w                   ; 2 chu kỳ đọc, mỗi chu kỳ thêm Tw\n        INC     AX\n        MOV     w, AX                   ; 2 chu kỳ ghi\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy: w ở độ lệch 1 nên mỗi lệnh MOV word là 2 chu kỳ bus, và mỗi chu kỳ chịu đủ trạng thái chờ. Với 2 Tw (đặt sẵn): 91 + 4 chu kỳ bus × 2 = 99, trong khi căn chẵn chỉ thêm 2 × 2 = 4. Đoán trước: lệnh MOV w, AX ghi byte nào trong chu kỳ đầu? Đáp án 79h ở 07121h."}, {"label": "Lỗi: chờ thiết bị bằng vòng lặp không thoát", "code": "; Ví dụ 6 (lỗi): chờ thiết bị bằng vòng lặp không thoát\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntt      DB      ?                       ; trạng thái đọc được\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     DX, 0305H               ; cổng trạng thái giả định\ncho:\n        IN      AL, DX                  ; đọc trạng thái\n        TEST    AL, 80H                 ; bit 7 = 0 nghĩa là sẵn sàng\n        JNZ     cho                     ; cổng trống đọc FFh: lặp mãi\n        MOV     tt, AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi cố ý: chương trình chờ bit 7 của cổng trạng thái 0305h (giả định) về 0. Cổng chưa gắn thiết bị nên đọc FFh mãi, vòng lặp không thoát; trình mô phỏng dừng ở giới hạn 2 000 000 lệnh. Đây là chờ bằng phần mềm, khác READY. Sửa: chỉ chờ thiết bị có thật, và đặt giới hạn số lần thử rồi báo lỗi. Đoán trước: lệnh JNZ cho có nhảy không? Đáp án có."}];
const sim34=makeX86Sim(document.getElementById("x86-l34"),{id:"s34",presets:P34,file:"BAI34.ASM"});
makeX86Ex(document.getElementById("ex-l34"),sim34,[{"t": "Số trạng thái chờ cần chèn", "d": "Nhập 3 chữ số: thời gian truy cập tACC của bộ nhớ, tính bằng ns (100–999). Theo mô hình của bài (8086 ở 5 MHz, giả định trễ chốt và bộ đệm 30 ns mỗi loại), khi không chờ bộ nhớ có 400 ns, mỗi trạng thái chờ thêm 200 ns. In số trạng thái chờ N nhỏ nhất để tACC ≤ 400 + 200·N (một chữ số) và ghi N vào biến soCho. Code mẫu có sẵn DOCN (đọc CX chữ số thập phân vào AX).", "start": "; Bài tập 1: số trạng thái chờ cần chèn\n; Nhập 3 chữ số: thời gian truy cập của bộ nhớ (ns).\n; Mô hình của bài: không chờ thì bộ nhớ có 400 ns,\n; mỗi Tw thêm 200 ns. In số Tw nhỏ nhất, ghi soCho.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntacc    DW      ?                       ; thời gian truy cập (ns)\nsoCho   DB      ?                       ; số trạng thái chờ\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     CX, 3\n        CALL    DOCN\n        MOV     tacc, AX\n; Viết code ở đây\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n; DOCn: đọc n chữ số thập phân vào AX (n trong CX)\nDOCN:\n        XOR     BX, BX\ndn:\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'\n        MOV     AH, 0\n        PUSH    AX                      ; giữ chữ số vừa đọc\n        MOV     AX, 10\n        MUL     BX                      ; AX = BX x 10\n        POP     BX\n        ADD     AX, BX\n        MOV     BX, AX\n        LOOP    dn\n        MOV     AX, BX\n        RET\n        END     MAIN\n", "tests": [{"in": "450", "out": "1", "mem": [{"at": "soCho", "bytes": [1]}]}, {"in": "250", "out": "0", "mem": [{"at": "soCho", "bytes": [0]}]}, {"in": "400", "out": "0", "mem": [{"at": "soCho", "bytes": [0]}]}, {"in": "401", "out": "1", "mem": [{"at": "soCho", "bytes": [1]}]}, {"in": "600", "out": "1", "mem": [{"at": "soCho", "bytes": [1]}]}, {"in": "601", "out": "2", "mem": [{"at": "soCho", "bytes": [2]}]}, {"in": "999", "out": "3", "mem": [{"at": "soCho", "bytes": [3]}]}]}, {"t": "Tần số CLK và PCLK", "d": "Nhập 5 chữ số: tần số thạch anh nối vào 8284A, tính bằng kHz (00003–65535). In tần số CLK cấp cho 8086 và tần số PCLK cho ngoại vi, tính bằng kHz, lấy phần nguyên, cách nhau một dấu cách (ví dụ 5000 2500). Ghi CLK vào biến clk (word). Code mẫu có sẵn DOCN và INSO (in AX dạng thập phân).", "start": "; Bài tập 2: tần số CLK và PCLK của 8284A\n; Nhập 5 chữ số: tần số thạch anh (kHz). In tần số CLK\n; và PCLK (kHz, phần nguyên), cách nhau một dấu cách.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntha     DW      ?                       ; tần số thạch anh (kHz)\nclk     DW      ?                       ; tần số CLK (kHz)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     CX, 5\n        CALL    DOCN\n        MOV     tha, AX\n; Viết code ở đây (INSO in AX dạng thập phân)\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n; DOCn: đọc n chữ số thập phân vào AX (n trong CX)\nDOCN:\n        XOR     BX, BX\ndn:\n        MOV     AH, 08H\n        INT     21H\n        SUB     AL, '0'\n        MOV     AH, 0\n        PUSH    AX                      ; giữ chữ số vừa đọc\n        MOV     AX, 10\n        MUL     BX                      ; AX = BX x 10\n        POP     BX\n        ADD     AX, BX\n        MOV     BX, AX\n        LOOP    dn\n        MOV     AX, BX\n        RET\n; INSO: in AX ở dạng thập phân (không có số 0 thừa ở đầu)\nINSO:\n        MOV     BX, 10\n        XOR     CX, CX\nis1:\n        XOR     DX, DX\n        DIV     BX                      ; AX = AX / 10, DX = chữ số cuối\n        PUSH    DX\n        INC     CX\n        TEST    AX, AX\n        JNZ     is1\n        MOV     AH, 02H\nis2:\n        POP     DX\n        ADD     DL, '0'\n        INT     21H\n        LOOP    is2\n        RET\n        END     MAIN\n", "tests": [{"in": "15000", "out": "5000 2500", "mem": [{"at": "clk", "bytes": [136, 19]}]}, {"in": "14318", "out": "4772 2386", "mem": [{"at": "clk", "bytes": [164, 18]}]}, {"in": "24000", "out": "8000 4000", "mem": [{"at": "clk", "bytes": [64, 31]}]}, {"in": "30000", "out": "10000 5000", "mem": [{"at": "clk", "bytes": [16, 39]}]}, {"in": "10000", "out": "3333 1666", "mem": [{"at": "clk", "bytes": [5, 13]}]}, {"in": "06000", "out": "2000 1000", "mem": [{"at": "clk", "bytes": [208, 7]}]}]}, {"t": "Chép khối ít chu kỳ bus", "d": "Code mẫu đọc 8 phím vào khối a rồi chép a sang b từng byte: 16 chu kỳ bus dữ liệu, mỗi chu kỳ lại chịu trạng thái chờ nếu bộ nhớ chậm. Giữ nguyên phần đọc phím, viết lại phần chép để chương trình đạt cả giới hạn chu kỳ và giới hạn byte mã (a, b đều ở địa chỉ chẵn). Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: chép khối qua bộ nhớ chậm\n; Bản này đúng nhưng mỗi byte tốn 2 chu kỳ bus.\n; Viết lại phần chép a → b cho nhanh hơn.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\na       DB      8 DUP(?)                ; khối nguồn (địa chỉ chẵn)\nb       DB      8 DUP(?)                ; khối đích (địa chỉ chẵn)\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     CX, 8                   ; đọc 8 phím vào a (giữ nguyên)\n        LEA     BX, a\ndoc:\n        MOV     AH, 08H\n        INT     21H\n        MOV     [BX], AL\n        INC     BX\n        LOOP    doc\n        LEA     SI, a                   ; chép a → b từng byte\n        LEA     DI, b\n        MOV     CX, 8\nchep:\n        MOV     AL, [SI]\n        MOV     [DI], AL\n        INC     SI\n        INC     DI\n        LOOP    chep\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "ABCDEFGH", "mem": [{"at": "a", "bytes": [65, 66, 67, 68, 69, 70, 71, 72]}, {"at": "b", "bytes": [65, 66, 67, 68, 69, 70, 71, 72]}]}, {"in": "12345678", "mem": [{"at": "a", "bytes": [49, 50, 51, 52, 53, 54, 55, 56]}, {"at": "b", "bytes": [49, 50, 51, 52, 53, 54, 55, 56]}]}, {"in": "aaaaaaaa", "mem": [{"at": "a", "bytes": [97, 97, 97, 97, 97, 97, 97, 97]}, {"at": "b", "bytes": [97, 97, 97, 97, 97, 97, 97, 97]}]}, {"in": "Z0Y1X2W3", "mem": [{"at": "a", "bytes": [90, 48, 89, 49, 88, 50, 87, 51]}, {"at": "b", "bytes": [90, 48, 89, 49, 88, 50, 87, 51]}]}, {"in": "~!@#$%^&", "mem": [{"at": "a", "bytes": [126, 33, 64, 35, 36, 37, 94, 38]}, {"at": "b", "bytes": [126, 33, 64, 35, 36, 37, 94, 38]}]}, {"in": "8086bus.", "mem": [{"at": "a", "bytes": [56, 48, 56, 54, 98, 117, 115, 46]}, {"at": "b", "bytes": [56, 48, 56, 54, 98, 117, 115, 46]}]}], "perf": {"cycles": 910, "bytes": 48}}]);
makeX86Bus(document.getElementById("bus-l34"),{presets:[Object.assign({},P34[0],{"wm": 1, "wi": 0}),Object.assign({},P34[1],{"wm": 0, "wi": 2}),Object.assign({},P34[2],{"wm": 1, "wi": 0}),Object.assign({},P34[3],{"wm": 1, "wi": 0}),Object.assign({},P34[4],{"wm": 2, "wi": 0}),Object.assign({},P34[5],{"wm": 0, "wi": 1})],modes:["min"]});

makeQuiz("quiz34","score34",[{"q": "Một bo 8086 dùng 8284A với thạch anh 15 MHz. CPU nhận xung nhịp CLK tần số bao nhiêu?", "o": ["15 MHz, đúng bằng tần số của thạch anh", "5 MHz, hệ số làm việc khoảng 33 %", "7,5 MHz, vì 8284A chia tần số cho 2", "2,5 MHz, vì CPU dùng chân PCLK của 8284A"], "a": 1, "e": "8284A chia tần số thạch anh cho 3 để có CLK 33 %: 15 / 3 = 5 MHz. PCLK = CLK / 2 = 2,5 MHz là xung cho ngoại vi; OSC mới bằng tần số thạch anh."}, {"q": "Ngay sau RESET, 8086 nạp lệnh đầu tiên ở địa chỉ vật lý nào?<pre class=\"mp-asm\">CS = FFFFh, IP = 0000h<\/pre>", "o": ["FFFF0h", "00000h", "FFFFFh", "0FFFFh"], "a": 0, "e": "Địa chỉ vật lý = CS × 16 + IP = FFFF0h + 0 = FFFF0h. Còn 16 byte tới đỉnh 1 MB nên ở đó thường là một JMP xa. 00000h là đầu bảng vectơ ngắt; 0FFFFh là nhầm khi quên nhân CS với 16."}, {"q": "Theo mô hình của bài (t<sub>có<\/sub> = 400 + 200·N ns ở 5 MHz), một EPROM có thời gian truy cập 550 ns cần mấy trạng thái chờ?", "o": ["0 trạng thái chờ, vì 550 ns ngắn hơn chu kỳ bus 800 ns", "2 trạng thái chờ, vì làm tròn 550 / 200 lên 3 rồi trừ 1", "1 trạng thái chờ, vì 400 < 550 ≤ 600", "3 trạng thái chờ, vì 550 / 200 làm tròn lên bằng 3"], "a": 2, "e": "Không chờ, bộ nhớ chỉ có 400 ns (không phải cả 800 ns của chu kỳ bus: phải trừ thời gian đặt địa chỉ, trễ chốt, bộ đệm, thời gian thiết lập). N = 1 cho 600 ns ≥ 550 ns."}, {"q": "Bộ nhớ có 2 trạng thái chờ. Đoạn code sau tốn bao nhiêu chu kỳ (x, y là word ở địa chỉ chẵn; không tính nạp lệnh)?<pre class=\"mp-asm\">        MOV     AX, x                   ; 10 theo bảng\n        MOV     y, AX                   ; 10 theo bảng<\/pre>", "o": ["20: trạng thái chờ không đổi số chu kỳ", "22: chỉ chu kỳ đọc mới phải chờ bộ nhớ", "24: hai chu kỳ bus, mỗi chu kỳ thêm 2", "28: mỗi lệnh thêm 2 cho cả đọc và ghi"], "a": 2, "e": "Mỗi lệnh có đúng một chu kỳ bus dữ liệu (word chẵn). Mỗi chu kỳ bus thêm N = 2 xung nhịp: 10 + 2 + 10 + 2 = 24. Chu kỳ ghi cũng chịu trạng thái chờ (Ví dụ 1)."}, {"q": "Thiết bị ở cổng 0305h chậm. Cách nào làm CPU chờ thiết bị mà chương trình không phải viết vòng lặp?", "o": ["Mạch giải mã kéo RDY của 8284A khi chọn cổng 0305h, CPU chèn Tw", "Viết vòng lặp IN AL, DX / TEST AL, 80h / JNZ cho tới khi sẵn sàng", "Hạ tần số thạch anh xuống để mọi chu kỳ bus đều dài hơn", "Đặt cờ IF = 0 bằng CLI để CPU chạy chậm lại khi đọc cổng"], "a": 0, "e": "READY làm dài đúng chu kỳ bus tới thiết bị chậm, phần mềm không thấy. Vòng lặp hỏi trạng thái là chờ bằng phần mềm (Ví dụ 6). Hạ tần số làm chậm cả hệ; CLI chỉ che ngắt."}]);

